import static org.assertj.core.api.Assertions.assertThat;

import jakarta.persistence.EntityManagerFactory;
import java.util.Map;
import javax.sql.DataSource;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.jpa.repository.config.EnableJpaRepositories;
import org.springframework.orm.jpa.JpaTransactionManager;
import org.springframework.orm.jpa.LocalContainerEntityManagerFactoryBean;
import org.springframework.orm.jpa.vendor.HibernateJpaVendorAdapter;
import org.springframework.test.context.junit.jupiter.SpringJUnitConfig;
import org.springframework.transaction.PlatformTransactionManager;

// Building the repositories parses every declared query and derives every query
// method from its name, so a bad query fails here rather than at startup. The
// dialect is named and metadata access is off, so no database is contacted.
@SpringJUnitConfig(RepositoriesTests.NoDatabase.class)
class RepositoriesTests {

    @Autowired OrderRepository orders;
    @Autowired OrderLineRepository lines;
    @Autowired CustomerRepository customers;
    @Autowired ItemRepository items;

    @Test
    void everyQueryIsValid() {
        assertThat(orders).isNotNull();
        assertThat(lines).isNotNull();
        assertThat(customers).isNotNull();
        assertThat(items).isNotNull();
    }

    @Configuration
    @EnableJpaRepositories(basePackageClasses = OrderRepository.class)
    static class NoDatabase {

        @Bean
        DataSource dataSource() {
            return Mockito.mock(DataSource.class);
        }

        @Bean
        LocalContainerEntityManagerFactoryBean entityManagerFactory(DataSource dataSource) {
            LocalContainerEntityManagerFactoryBean factory =
                    new LocalContainerEntityManagerFactoryBean();
            factory.setDataSource(dataSource);
            factory.setPackagesToScan(Order.class.getPackageName());
            factory.setJpaVendorAdapter(new HibernateJpaVendorAdapter());
            factory.setJpaPropertyMap(Map.of(
                    "hibernate.dialect", "org.hibernate.dialect.PostgreSQLDialect",
                    "hibernate.boot.allow_jdbc_metadata_access", "false",
                    "jakarta.persistence.schema-generation.database.action", "none"));
            return factory;
        }

        @Bean
        PlatformTransactionManager transactionManager(EntityManagerFactory factory) {
            return new JpaTransactionManager(factory);
        }
    }
}
